test_that("MV17-C closure v1 is explicitly rejected only for elapsed-time accounting", {
  root<-testthat::test_path("..","..");a<-file.path(root,"docs","audits","mv17c-calibration-closure-v1-rejection-v2");skip_if_not(dir.exists(a),"MV17-C time-parser failure record absent");r<-function(n)read.csv(file.path(a,n),stringsAsFactors=FALSE,check.names=FALSE);f<-r("mv17c-time-parser-failure.csv");m<-r("mv17c-time-parser-failure-artifact-manifest.csv");expect_equal(nrow(f),2L);expect_equal(f$omitted_seconds,c(780,240),tolerance=1e-9);expect_false(any(f$scientific_artifact_changed));expect_false(any(f$production_rerun_authorized));expect_false(any(f$closure_v1_committable));files<-file.path(a,m$artifact);expect_equal(as.numeric(file.info(files)$size),m$bytes);expect_equal(unname(vapply(files,digest::digest,character(1L),algo="sha256",file=TRUE,serialize=FALSE)),unname(m$sha256))
})

test_that("MV17-C closure-only recovery is prospectively frozen", {
  root<-testthat::test_path("..","..");a<-file.path(root,"docs","audits","mv17c-calibration-time-recovery-prefreeze-v1");skip_if_not(dir.exists(a),"MV17-C time recovery prefreeze absent");r<-function(n)read.csv(file.path(a,n),stringsAsFactors=FALSE,check.names=FALSE);v<-r("mv17c-time-recovery-validation.csv");c<-r("mv17c-time-recovery-contract.csv");m<-r("mv17c-time-recovery-artifact-manifest.csv");expect_equal(nrow(v),14L);expect_true(all(v$passed));expect_equal(c$production_jobs,260L);expect_false(c$production_rerun_authorized);expect_false(c$scientific_recomputation_authorized);expect_true(c$closure_v2_authorized_after_commit);files<-file.path(a,m$artifact);expect_equal(as.numeric(file.info(files)$size),m$bytes);expect_equal(unname(vapply(files,digest::digest,character(1L),algo="sha256",file=TRUE,serialize=FALSE)),unname(m$sha256))
})
